/// A grid's fixed track count from `prop`: a positive finite Fixed value pins
/// the count; `FILL`/absent → auto-fit (`None`).
fn grid_count(node: &Node, prop: u16) -> Option<u32> {
    let v = node.f32_property(prop, -1.0);
    if v <= 0.0 {
        None
    } else {
        Some(v.round() as u32)
    }
}

