fn grid_matches(grid: &gtk::Grid, cells: &[(u32, u32, u32)], widgets: &HashMap<u32, gtk::Widget>) -> bool {
    if child_widgets(&grid.clone().upcast()).len() != cells.len() {
        return false;
    }
    for (cell, row, col) in cells {
        let Some(w) = widgets.get(cell) else { return false };
        if grid.child_at(*col as i32, *row as i32).as_ref() != Some(w) {
            return false;
        }
    }
    true
}
