fn grid_tracks_css(node: &Node) -> Option<String> {
    let tracks = grid_tracks(node)?;
    let mut out = String::new();
    for t in tracks {
        if !out.is_empty() {
            out.push(' ');
        }
        if let Some(pts) = t.strip_prefix("fixed:") {
            out.push_str(&format!("{pts}px"));
