```rust
/// Horizontal position of an `ALIGNMENT` code (0–8, spec PRIMITIVES.md §ZStack).
fn align_h(code: u8) -> &'static str {
    match code { 1 | 3 | 4 => "center", 2 | 6 | 7 => "end", _ => "start" }
}
/// Vertical position of an `ALIGNMENT` code.
fn align_v(code: u8) -> &'static str {
    match code { 1 | 5 | 6 => "center", 2 | 4 | 8 => "end", _ => "start" }
}
```

