```rust
use std::time::Duration;
use pathland_core_transport::{DriverTransport, FrameSource, RingTransport};
use crate::TuiRenderer;
use ratatui::backend::CrosstermBackend;
use ratatui::crossterm::event::{self, Event as TermEvent, KeyCode, KeyEventKind};
use ratatui::crossterm::execute;
use ratatui::crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::Terminal;
use std::io::stdout;

pub fn run(ring: &mut RingTransport, mut wake: impl FnMut()) {
    let mut renderer = TuiRenderer::new();
    // Apply any initial frames.
    apply_pending(ring, &mut renderer);

    let mut terminal = Terminal::new(CrosstermBackend::new(stdout())).expect("terminal");
    enable_raw_mode().expect("raw mode");
    execute!(stdout(), EnterAlternateScreen).expect("alt screen");

    let mut quit = false;
    while !quit {
        apply_pending(ring, &mut renderer);
        terminal.draw(|f| renderer.draw(f, f.area())).expect("draw");
        renderer.tick();

        let polled = event::poll(Duration::from_millis(100)).unwrap_or(false);
        if !polled { continue; }
        if let Ok(ev) = event::read() {
            match &ev {
                TermEvent::Key(k) if k.kind == KeyEventKind::Press => {
                    if k.code == KeyCode::Char('q') || k.code == KeyCode::Esc || (k.code == KeyCode::Char('c') && k.modifiers.contains(KeyModifiers::CONTROL)) { quit = true; }
                    else { handle(ring, &mut renderer, &mut wake, ev); }
                }
                TermEvent::Resize(..) => {}
                _ => handle(ring, &mut renderer, &mut wake, ev),
            }
        }
    }

    execute!(stdout(), LeaveAlternateScreen).expect("leave alt");
    disable_raw_mode().expect("raw off");
}
```

