fn on_text_key(&mut self, fid: u32, node: &HostNode, k: &KeyEvent) -> Vec<Event> {
    let mut out = Vec::new();
    let current = node.text.clone().unwrap_or_default();
    let new = match k.code {
        KeyCode::Char(c) if !k.modifiers.contains(CONTROL) => {
            let mut s = current; s.push(c); s
        }
        KeyCode::Backspace => { let mut s = current; s.pop(); s }
        KeyCode::Enter => { /* submit */ current }
        _ => return self.key_event(fid, k),
    };
    if node.u32_property(BINDING_ID, 0) != 0 {
        out.push(Event::TextChanged { target: fid, value: new });
    }
    if k.code == KeyCode::Enter && self.node_wants(fid, listener::SUBMIT) {
        out.push(Event::Submit { target: fid });
    }
    // Also forward KEY_DOWN/UP if the node wants them.
    out.extend(self.key_event(fid, k));
    out
}
```
