fn adjust_value(&self, fid, node, dir: i32) -> Vec<Event> {
    let min = node.f32_property(MIN_VALUE, 0.0);
    let max = node.f32_property(MAX_VALUE, 100.0);
    let step = node.f32_property(STEP_VALUE, 1.0).max(0.01);
    let cur = node.f32_property(VALUE, min);
    let mut v = cur + dir as f32 * step;
    if v < min { v = min; }
    if v > max { v = max; }
    if node.u32_property(BINDING_ID, 0) != 0 {
        vec![Event::ValueChanged { target: fid, value: v }]
    } else { vec![] }
}
