use std::cell::RefCell;
use std::io::stdout;
use std::rc::Rc;
use std::time::Duration;

use pathland_core_transport::{DriverTransport, FrameSource, RingTransport};
use ratatui::backend::CrosstermBackend;
use ratatui::crossterm::event::{self, Event as TermEvent, KeyCode, KeyEventKind, KeyModifiers};
use ratatui::crossterm::execute;
use ratatui::crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::Terminal;

use crate::TuiRenderer;

/// The transport surface the TUI event loop pumps: frames in, events out.
pub trait Pump: FrameSource + DriverTransport {}
impl<T: FrameSource + DriverTransport> Pump for T {}

/// Run the TUI renderer to completion over `pump`.
///
/// Applies pending frames, redraws the terminal each loop, routes raw input
/// (mouse + keyboard) into protocol `Event`s written through the pump, and
/// calls `wake` whenever events were written (the host drains them itself).
/// Quit with `q` or Ctrl+C (a focused text input consumes `q`); Esc clears
/// focus or sends a `NAVIGATE` back request.
pub fn run<P: Pump>(pump: Rc<RefCell<P>>, mut wake: impl FnMut()) {
    let mut renderer = TuiRenderer::new();
    apply_pending(&mut pump.borrow_mut(), &mut renderer);

    let _ = enable_raw_mode();
    let mut terminal = Terminal::new(CrosstermBackend::new(stdout())).expect("terminal backend");
    let _ = execute!(stdout(), EnterAlternateScreen);

    let mut quit = false;
    while !quit {
        {
            let mut p = pump.borrow_mut();
            apply_pending(&mut p, &mut renderer);
        }
        let _ = terminal.draw(|f| renderer.draw(f, f.area()));
        renderer.tick();

        if !event::poll(Duration::from_millis(100)).unwrap_or(false) {
            continue;
        }
        let Ok(ev) = event::read() else { continue };
        match &ev {
            TermEvent::Key(k) if k.kind == KeyEventKind::Press => {
                let ctrl_c = k.code == KeyCode::Char('c') && k.modifiers.contains(KeyModifiers::CONTROL);
                let quit_q = k.code == KeyCode::Char('q') && !renderer.has_text_focus();
                if ctrl_c || quit_q {
                    quit = true;
                } else if k.code == KeyCode::Esc {
                    if renderer.has_text_focus() {
                        renderer.set_focus(None);
                    } else {
                        handle(&pump, &mut renderer, &mut wake, TermEvent::NavigateBack);
                    }
                } else {
                    handle(&pump, &mut renderer, &mut wake, ev);
                }
            }
            TermEvent::Resize(..) => {}
            _ => handle(&pump, &mut renderer, &mut wake, ev),
        }
    }

    let _ = execute!(stdout(), LeaveAlternateScreen);
    let _ = disable_raw_mode();
}
```

