package com.pathland.demo.tui;

import com.sun.jna.Callback;
import com.sun.jna.Library;
import com.sun.jna.Native;
import com.sun.jna.Pointer;
import java.io.File;

public final class TuiRendererNative {
    public interface EventCallback extends Callback { void invoke(); }
    private interface NativeTuiRenderer extends Library {
        void pathland_tui_run_ring(Pointer ring, EventCallback onEvent);
    }
    private static final class Holder { static final TuiRendererNative INSTANCE = new TuiRendererNative(); }
    public static TuiRendererNative instance() { return Holder.INSTANCE; }
    private final NativeTuiRenderer nativeTui;
    private TuiRendererNative() {
        String libraryPath = resolveLibraryPath();
        if (libraryPath == null) {
            throw new IllegalStateException("libpathland_render_tui not found; set -Dpathland.tui.lib to its full path (cargo build -p pathland-render-tui)");
        }
        this.nativeTui = Native.load(libraryPath, NativeTuiRenderer.class);
    }
    public void runRing(Pointer ring, EventCallback onEvent) { nativeTui.pathland_tui_run_ring(ring, onEvent); }
    static String resolveLibraryPath() {
        String override = System.getProperty("pathland.tui.lib");
        if (override != null) return override;
        String fileName = "libpathland_render_tui" + platformLibraryExtension();
        String libraryPath = System.getProperty("java.library.path");
        if (libraryPath == null) return null;
        for (String dir : libraryPath.split(File.pathSeparator)) {
            File candidate = new File(dir, fileName);
            if (candidate.isFile()) return candidate.getAbsolutePath();
        }
        return null;
    }
    private static String platformLibraryExtension() { ... same as GTK ... }
}
