import java.io.File;

/**
 * JNA binding to the Rust Ratatui renderer cdylib ({@code libpathland_render_tui}).
 *
 * <p>The Java DSL emits opcodes into a {@code libpathland_core} ring
 * ({@code com.pathland.view.ffm.RingOpcodeSink}); {@link #runRing} hands that
 * borrowed ring to the in-process TUI renderer ({@code pathland_tui_run_ring}),
 * which pumps it in place and redraws the terminal. Raw inputs are reported
 * back through a no-payload callback; the host drains them from the ring
 * itself — the wire is the opcode engine, never a side-channel callback.
 *
 * <p>Library resolution: the {@code pathland.tui.lib} system property, else
 * {@code libpathland_render_tui} searched on {@code java.library.path}.
 */
public final class TuiRendererNative {

    /** Invoked (with no payload) after a raw input was written to the ring. */
    public interface EventCallback extends Callback {
        void invoke();
    }

    /** The C ABI surface, mapped by JNA onto the Rust cdylib. */
    private interface NativeTuiRenderer extends Library {
        void pathland_tui_run_ring(Pointer ring, EventCallback onEvent);
    }

    private static final class Holder {
        static final TuiRendererNative INSTANCE = new TuiRendererNative();
    }

    /** The process-wide binding; lazily links {@code libpathland_render_tui} on first call. */
    public static TuiRendererNative instance() {
        return Holder.INSTANCE;
    }

    private final NativeTuiRenderer nativeTui;

    private TuiRendererNative() {
        String libraryPath = resolveLibraryPath();
        if (libraryPath == null) {
            throw new IllegalStateException(
                    "libpathland_render_tui not found; set -Dpathland.tui.lib to its full path "
                            + "(cargo build -p pathland-render-tui)");
        }
        this.nativeTui = Native.load(libraryPath, NativeTuiRenderer.class);
    }

    /**
     * Run the TUI renderer over the borrowed ring (from {@code PathlandCore.ringMut}).
     * Blocks until the user quits ({@code q} / {@code Ctrl+C}).
     *
     * @param ring    the opaque ring pointer (must outlive this call)
     * @param onEvent wake callback (nullable)
     */
    public void runRing(Pointer ring, EventCallback onEvent) {
        nativeTui.pathland_tui_run_ring(ring, onEvent);
    }

    /** Resolve the native library's full path (system property, then {@code java.library.path}). */
    static String resolveLibraryPath() {
        String override = System.getProperty("pathland.tui.lib");
        if (override != null) {
            return override;
        }
        String fileName = "libpathland_render_tui" + platformLibraryExtension();
        String libraryPath = System.getProperty("java.library.path");
        if (libraryPath == null) {
            return null;
        }
        for (String dir : libraryPath.split(File.pathSeparator)) {
            File candidate = new File(dir, fileName);
            if (candidate.isFile()) {
                return candidate.getAbsolutePath();
            }
        }
        return null;
    }

    private static String platformLibraryExtension() {
        String os = System.getProperty("os.name", "").toLowerCase(java.util.Locale.ROOT);
        if (os.contains("mac")) {
            return ".dylib";
        }
        if (os.contains("win")) {
            return ".dll";
        }
        return ".so";
    }
}

package com.pathland.demo.tui;

import com.pathland.demo.DemoTheme;
import com.pathland.demo.music.MusicPlayerView;
import com.pathland.view.Environment;
import com.pathland.view.emit.Emitter;
import com.pathland.view.emit.InputDispatcher;
import com.pathland.view.emit.RenderResult;
import com.pathland.view.ffm.PathlandCore;
import com.pathland.view.ffm.RingOpcodeSink;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;
import com.pathland.view.state.InMemoryStateStore;
import com.pathland.view.state.PersistentState;
import com.sun.jna.Memory;
import com.sun.jna.Pointer;

/**
 * Runs the shared {@link MusicPlayerView} under the native Ratatui renderer —
 * the cross-language, shared-renderer story for Java, in the terminal.
 *
 * <p>The Java DSL mounts the view through its fine-grained {@link Emitter} into a
 * {@code libpathland_core} shared ring ({@link RingOpcodeSink}, zero-copy). The
 * in-process TUI renderer pumps the same ring in place
 * ({@code pathland_tui_run_ring}); terminal inputs (mouse + keyboard) round-trip
 * as {@code EVENT} opcodes that this host drains and dispatches through
 * {@link InputDispatcher} into the app's bindings (taps, value inputs, router
 * back). The renderer is the wire — no Swing, no GTK, only Pathland authoring.
 *
 * <p>Audio playback and album covers have no terminal equivalent yet: the
 * {@code AUDIO}/{@code IMAGE} nodes render as placeholders, and the scrollable
 * track list shows its first child (scrolling is a renderer follow-up). The
 * player's controls (play/pause/next/prev, volume + seek sliders) work with the
 * mouse or Tab + arrows; quit with {@code q} or {@code Ctrl+C}.
 *
 * <p>Run (one-time: build the Rust dylibs, then the Java reactor):
 * <pre>{@code
 *   cargo build -p pathland-core-capi -p pathland-render-tui
 *   cd lib/java && mvn -q install
 *   cd pathland-tui-demo
 *   mvn -q compile exec:java \
 *     -Dpathland.core.lib=$PWD/../../lib/rust/target/debug/libpathland_core.dylib \
 *     -Dpathland.tui.lib=$PWD/../../lib/rust/target/debug/libpathland_render_tui.dylib
 * }</pre>
 */
public final class TuiHost {

    /** Max events drained per wake (× 16 bytes each). */
    private static final int MAX_EVENTS = 64;

    public static void main(String[] args) {
        PathlandCore core = PathlandCore.instance();
        try (RingOpcodeSink sink = new RingOpcodeSink(core)) {
            Pointer handle = sink.handle();

            // The session's state + theme, exactly as the server session seeds them.
            PersistentState state = new PersistentState(new InMemoryStateStore(), "tui");
            // A placeholder host path signal: MusicPlayerView has no router, so the
            // dispatcher's NAVIGATE handling is never exercised with a URL.
            WritableSignal<String> activePath = Signals.signal("/");

            Emitter emitter = new Emitter(sink, DemoTheme.adaptive());
            RenderResult result = emitter.mount(
                    new MusicPlayerView(),
                    new Environment(state));
            InputDispatcher dispatcher = new InputDispatcher(result, activePath);
            RingEventReader reader =
                    new RingEventReader(core.ringPtr(handle), core.ringLen(handle));

            // Wake callback: drain raw EVENT opcodes from the shared ring and route
            // them into the app's bindings. Re-emission (signal → emitter → ring)
            // happens on this thread after the wake, the only writer.
            TuiRendererNative.EventCallback onEvent = () -> {
                Memory buf = new Memory((long) MAX_EVENTS * 16);
                int n = core.drainEvents(handle, buf, MAX_EVENTS);
                if (n > 0) {
                    byte[] raw = buf.getByteArray(0, n * 16);
                    dispatcher.dispatch(reader.decode(raw));
                }
            };

            // Blocks until the user quits (q / Ctrl+C); the ring (handle) must
            // outlive it.
            TuiRendererNative renderer = TuiRendererNative.instance();
            renderer.runRing(core.ringMut(handle), onEvent);
        }
    }
}

package com.pathland.demo.tui;

import com.pathland.view.Commands;
import com.pathland.view.transport.Event;
import com.sun.jna.Pointer;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Decodes raw {@code EVENT}-category opcodes drained from the shared ring
 * ({@code pathland_core_drain_events}) into {@link Event} objects, resolving
 * strings ({@code TEXT_CHANGED}, {@code NAVIGATE} URLs) from the shared
 * host → guest event arena. The wire is the opcode engine — never a
 * side-channel callback.
 */
public final class RingEventReader {

    private static final int OPCODE_SIZE = 16;
    private static final int CATEGORY_EVENT = 0x03;

    /** Ring header: byte offset of the event-arena offset (spec/OPCODE.md, memory.rs). */
    private static final int OFF_EVENT_ARENA_OFFSET = 0x40;

    private final Pointer ringPtr;
    private final long ringLen;
    private final int eventArenaOffset;

    public RingEventReader(Pointer ringPtr, long ringLen) {
        this.ringPtr = ringPtr;
        this.ringLen = ringLen;
        if (ringPtr != null && ringLen >= OFF_EVENT_ARENA_OFFSET + 4L) {
            this.eventArenaOffset = ringPtr.getInt(OFF_EVENT_ARENA_OFFSET);
        } else {
            this.eventArenaOffset = 0;
        }
    }

    /** Decode consecutive 16-byte opcodes from {@code raw} (a drain buffer). */
    public List<Event> decode(byte[] raw) {
        List<Event> events = new ArrayList<>();
        for (int off = 0; off + OPCODE_SIZE <= raw.length; off += OPCODE_SIZE) {
            if ((raw[off] & 0xFF) != CATEGORY_EVENT) {
                continue;
            }
            int command = raw[off + 1] & 0xFF;
            int flags = u16(raw, off + 2);
            int a = i32(raw, off + 4);
            int b = i32(raw, off + 8);
            int c = i32(raw, off + 12);
            Event event = decodeOne(command, flags, a, b, c);
            if (event != null) {
                events.add(event);
            }
        }
        return events;
    }

    private Event decodeOne(int command, int flags, int a, int b, int c) {
        return switch (command) {
            case Commands.Event.POINTER_DOWN -> Event.pointerDown(a, f32(b), f32(c));
            case Commands.Event.POINTER_UP -> Event.pointerUp(a, f32(b), f32(c));
            case Commands.Event.POINTER_MOVE -> Event.pointerMove(a, f32(b), f32(c), flags);
            case Commands.Event.KEY_DOWN -> Event.keyDown(a, b, c, flags);
            case Commands.Event.KEY_UP -> Event.keyUp(a, b, c);
            case Commands.Event.VALUE_CHANGED -> Event.valueChanged(a, f32(b));
            case Commands.Event.TEXT_CHANGED -> Event.textChanged(a, arenaString(b));
            case Commands.Event.FOCUS_CHANGED -> Event.focusChanged(a, b != 0);
            case Commands.Event.EDITING_CHANGED -> Event.editingChanged(a, b != 0);
            case Commands.Event.SUBMIT -> Event.submit(a);
            case Commands.Event.SCROLL -> Event.scroll(a, f32(b), f32(c));
            case Commands.Event.WHEEL -> Event.wheel(a, f32(b), f32(c));
            case Commands.Event.DATE_CHANGED -> Event.dateChanged(a, b, c);
            case Commands.Event.MEDIA_PLAY_STATE_CHANGED -> Event.mediaPlayStateChanged(a, b != 0);
            case Commands.Event.MEDIA_TIME_UPDATED -> Event.mediaTimeUpdated(a, f32(b));
            case Commands.Event.MEDIA_ENDED -> Event.mediaEnded(a);
            case Commands.Event.MEDIA_VOLUME_CHANGED -> Event.mediaVolumeChanged(a, f32(b));
            case Commands.Event.NAVIGATE -> (flags & Commands.Flags.NAVIGATE_URL) != 0
                    ? Event.navigate(arenaString(b))
                    : Event.navigateBack();
            default -> null;
        };
    }

    /** Resolve a string from the shared event arena at {@code ref} ([u32 len][bytes]). */
    private String arenaString(int ref) {
        if (ref < 0 || ringPtr == null || eventArenaOffset <= 0) {
            return null;
        }
        long base = (long) eventArenaOffset + ref;
        if (base + 4 > ringLen) {
            return null;
        }
        int len = ringPtr.getInt(base);
        if (len < 0 || base + 4 + len > ringLen) {
            return null;
        }
        byte[] bytes = ringPtr.getByteArray(base + 4, len);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    private static int u16(byte[] raw, int off) {
        return (raw[off] & 0xFF) | ((raw[off + 1] & 0xFF) << 8);
    }

    private static int i32(byte[] raw, int off) {
        return (raw[off] & 0xFF) | ((raw[off + 1] & 0xFF) << 8)
                | ((raw[off + 2] & 0xFF) << 16) | ((raw[off + 3] & 0xFF) << 24);
    }

    private static float f32(int bits) {
        return Float.intBitsToFloat(bits);
    }
}

