package com.pathland.server;

public final class DeltaBatcher {
    private final List<Opcode> opcodes = new ArrayList<>();
    private final ByteArrayOutputStream strings = new ByteArrayOutputStream();
    private final long flushIntervalMillis;
    private final int maxBatchBytes;
    private final ScheduledExecutorService scheduler;
    private final Consumer<byte[]> sender;  // sends an encoded batch
    private final AtomicBoolean flushScheduled = new AtomicBoolean(false);

    // state for bytes counting
    private int approxBytes;

    public DeltaBatcher(long flushIntervalMillis, int maxBatchBytes, Consumer<byte[]> sender) {
        ...
        scheduler = Executors.newSingleThreadScheduledExecutor(r -> { Thread t = new Thread(r, "pathland-delta-batcher"); t.setDaemon(true); return t; });
    }

    public synchronized void append(Frame frame) {
        if (frame.isEmpty()) return;
        int base = strings.size();
        // rebase string-referencing opcodes + append opcodes + strings
        for (Opcode op : frame.opcodes()) {
            opcodes.add(rebase(op, base, frame.strings()));
        }
        strings.writeBytes(frame.strings());
        approxBytes = ...;
        if (approxBytes >= maxBatchBytes) {
            flushNow();
        } else {
            scheduleFlush();
        }
    }

    public synchronized void flush() {
        if (opcodes.isEmpty()) { flushScheduled.set(false); return; }
        Frame merged = new Frame(List.copyOf(opcodes), strings.toByteArray());
        opcodes.clear();
        strings.reset();
        approxBytes = 0;
        flushScheduled.set(false);
        if (!merged.isEmpty()) {
            sender.accept(FrameCodec.encodeFrame(merged));
        }
    }

    public void close() { scheduler.shutdownNow(); }
}
```

