```java
package com.pathland.quarkus;

import com.pathland.server.PathlandConnection;
import io.quarkus.websockets.next.WebSocketConnection;

import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicBoolean;

final class QuarkusConnection implements PathlandConnection {

    private final WebSocketConnection connection;
    private final ConcurrentLinkedQueue<byte[]> pending = new ConcurrentLinkedQueue<>();
    private final AtomicBoolean sending = new AtomicBoolean(false);
    private volatile boolean failed = false;

    QuarkusConnection(WebSocketConnection connection) {
        this.connection = connection;
    }

    @Override
    public void send(byte[] bytes) {
        if (failed || !connection.isOpen()) {
            return;
        }
        pending.add(bytes);
        drain();
    }

    @Override
    public boolean isOpen() {
        return !failed && connection.isOpen();
    }

    /** Serialized send: at most one `sendBinary` subscription in flight; a send
     *  failure closes the connection so the session detects it and the client
     *  reconnects + re-syncs (spec EVENTS.md / server-side recovery). */
    private void drain() {
        if (!sending.compareAndSet(false, true)) {
            return;
        }
        byte[] next = pending.poll();
        if (next == null) {
            sending.set(false);
            return;
        }
        connection.sendBinary(next).subscribe().with(
                ignored -> {
                    sending.set(false);
                    drain();
                },
                failure -> {
                    sending.set(false);
                    failed = true;
                    connection.close().subscribe().with(ignored2 -> {}, ignored2 -> {});
                });
    }
}
```

