    @Test
    void allReferencedDemoAssetsResolveOnTheClasspath() {
        for (String asset : DemoAssets.ASSETS) {
            assertNotNull(DemoAssetsTest.class.getResourceAsStream(DemoAssets.RESOURCE_BASE + asset),
                    "missing shared demo asset: " + asset);
        }
    }

