    void extractToTempMaterializesEveryAsset() {
        java.nio.file.Path root = DemoAssets.extractToTemp();
        for (String asset : DemoAssets.ASSETS) {
            assertNotNull(root.resolve("assets").resolve(asset).toFile(),
                    "extraction missed: " + asset);
            assertNotNull(root.resolve("assets").resolve(asset).toFile().exists()
                            ? root.resolve("assets").resolve(asset).toFile()
                            : null,
                    "extraction missed: " + asset);
        }
    }
}

