package com.pathland.demo.music;

import com.pathland.view.signal.Signal;
import com.pathland.view.signal.WritableSignal;

import java.util.function.UnaryOperator;

/**
 * A {@link WritableSignal} (seconds) for the seek slider that **presents** the
 * playback position (the {@code MEDIA_TIME_UPDATED} display signal) but on a user
 * drag writes the **seek command** signal bound to {@code MEDIA_POSITION} (and
 * the display, for immediate thumb feedback). Decoupling the two is what stops a
 * position report from echoing back as a seek (spec/EVENTS.md Media).
 */
final class SeekControl implements WritableSignal<Float> {

    private final WritableSignal<Float> position;
    private final WritableSignal<Float> seekRequest;

    SeekControl(WritableSignal<Float> position, WritableSignal<Float> seekRequest) {
        this.position = position;
        this.seekRequest = seekRequest;
    }

    @Override
    public Float get() {
        return position.get();
    }

    @Override
    public void set(Float seconds) {
        // A user seek: update the thumb immediately AND emit the seek command.
        position.set(seconds);
        seekRequest.set(seconds);
    }

    @Override
    public void update(UnaryOperator<Float> fn) {
        set(fn.apply(get()));
    }

    @Override
    public Signal<Float> asReadonly() {
        return this::get;
    }
}

package com.pathland.demo.music;

import com.pathland.view.signal.Signal;
import com.pathland.view.signal.WritableSignal;

import java.util.function.UnaryOperator;

/**
 * A {@link WritableSignal} (0..1) for the volume slider that **presents** the
 * current volume (the {@code MEDIA_VOLUME_CHANGED} display signal) but on a user
 * drag writes the **volume command** signal bound to {@code MEDIA_VOLUME} (and
 * the display, for immediate feedback). Decoupling stops a volume report from
 * echoing back as a command (spec/EVENTS.md Media).
 */
final class VolumeControl implements WritableSignal<Float> {

    private final WritableSignal<Float> volume;
    private final WritableSignal<Float> volumeRequest;

    VolumeControl(WritableSignal<Float> volume, WritableSignal<Float> volumeRequest) {
        this.volume = volume;
        this.volumeRequest = volumeRequest;
    }

    @Override
    public Float get() {
        return volume.get();
    }

    @Override
    public void set(Float value) {
        volume.set(value);
        volumeRequest.set(value);
    }

    @Override
    public void update(UnaryOperator<Float> fn) {
        set(fn.apply(get()));
    }

    @Override
    public Signal<Float> asReadonly() {
        return this::get;
    }
}

