        MicrometerTelemetry telemetry = new MicrometerTelemetry(registry);
        telemetry.bindActiveSessions(() -> 3);
        telemetry.sessionOpened("/app");
        telemetry.sessionOpened("/app");
        telemetry.sessionClosed("/app");
        telemetry.eventBatchReceived("/app", 5);
        telemetry.batchFlushed("/app", 2, 7, 128, 1_000_000);
        telemetry.ssrRendered("/app", 2_000_000);
        telemetry.resyncRequested("/app");
        telemetry.connectionFailed("/app", "boom");

        assertEquals(2.0, registry.get("pathland.sessions.opened").tag("mount","/app").counter().count());
        assertEquals(1.0, registry.get("pathland.sessions.closed").tag("mount","/app").counter().count());
        assertEquals(5.0, registry.get("pathland.events.received").tag("mount","/app").counter().count());
        assertEquals(1.0, registry.get("pathland.batches.sent").tag("mount","/app").counter().count());
        assertEquals(2.0, registry.get("pathland.frames.sent").tag("mount","/app").counter().count());
        assertEquals(128.0, registry.get("pathland.bytes.sent").tag("mount","/app").counter().count());
        assertEquals(1, registry.get("pathland.ssr.render").tag("mount","/app").timer().count());
        assertEquals(1, registry.get("pathland.batch.flush").tag("mount","/app").timer().count());
        assertEquals(7.0, registry.get("pathland.batch.size").tag("mount","/app").summary().totalAmount());
        assertEquals(1.0, registry.get("pathland.resync.requested").tag("mount","/app").counter().count());
        assertEquals(1.0, registry.get("pathland.ws.failures").tag("mount","/app").counter().count());
